def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
D4=[(1,0),(-1,0),(0,1),(0,-1)]
for name in ['Demo pair 1','Demo pair 2']:
    I=np.array(G[name+' input']); O=np.array(G[name+' output'])
    H,W=I.shape
    zm=(I==0)
    comps=[]; seen=set()
    def cc(i,j):
        q=deque([(i,j)]); seen.add((i,j)); res=set()
        while q:
            a,b=q.popleft(); res.add((a,b))
            for di,dj in D4:
                x,y=a+di,b+dj
                if 0<=x<H and 0<=y<W and zm[x,y] and (x,y) not in seen:
                    seen.add((x,y)); q.append((x,y))
        return res
    for i in range(H):
        for j in range(W):
            if zm[i,j] and (i,j) not in seen:
                comps.append(cc(i,j))
    ch={(i,j) for i,j in zip(*np.where(I==0 and O!=0))}
    st={(i,j) for i,j in zip(*np.where(I==0 and O==0))}
    tag={c: 'ch' if c&ch else ('st' if c&st else '?') for c in comps}
    maxst=max((len(c) for c in comps if tag[c]=='st'),default=None)
    print(name,'comp counts:',dict(Counter(tag[c] for c in comps)),',tot zeros',sum(len(c) for c in comps),'largest-st comp size:',maxst,'sttot',len(st))

