        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<H and 0<=cc<W and I[rr,cc]==bg and not seen[rr,cc]:
                seen[rr,cc]=True; q.append((rr,cc))
    out=I.copy(); out[I==bg & ~seen]=3
    return out.astype(int)

